<script setup lang="ts">
import type { ApiEnvelope, LinkRecord } from '~/types/api'
definePageMeta({ layout:'dashboard', middleware:'auth' }); useSeoPage('Dashboard','Your 247URL dashboard overview.','/dashboard')
interface Summary { total_links:number; active_links:number; total_clicks:number; unique_visitors:number; clicks_today:number; clicks_this_month:number; recent_links:LinkRecord[]; top_links:LinkRecord[] }
const { user }=useAuth(); const {request}=useApi(); const { data,pending,error,refresh }=await useAsyncData('dashboard-summary',()=>request<ApiEnvelope<Summary>>('dashboard'))
const createOpen = ref(false)
const greeting=computed(()=>{const hour=new Date().getHours();return hour<12?'Good morning':hour<18?'Good afternoon':'Good evening'})
</script>
<template><div class="dashboard-page"><div class="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between"><div><h1 class="page-title">{{ greeting }}, {{ user?.name?.split(' ')[0] || 'there' }}.</h1><p class="mt-1 text-sm text-text-secondary">Manage your links and understand how they’re performing.</p></div><button type="button" class="btn-primary" @click="createOpen = true">+ Create link</button></div><LoadingState v-if="pending" class="mt-7"/><div v-else-if="error" class="surface mt-7 p-6"><h2 class="font-semibold">Dashboard unavailable</h2><p class="mt-2 text-sm text-text-secondary">Verify your email or try loading the workspace again.</p><button class="btn-secondary mt-4" @click="refresh()">Try again</button></div><template v-else-if="data"><div class="mt-7 grid grid-cols-2 gap-3 lg:grid-cols-4"><StatCard label="Total links" :value="data.data.total_links"/><StatCard label="Total clicks" :value="data.data.total_clicks.toLocaleString()" tone="violet"/><StatCard label="Unique visitors" :value="data.data.unique_visitors.toLocaleString()" tone="blue"/><StatCard label="Active links" :value="data.data.active_links" tone="green"/></div><div class="mt-5 grid gap-5 lg:grid-cols-[1.35fr_.65fr]"><section class="surface overflow-hidden"><div class="flex items-center justify-between border-b border-border px-5 py-4"><div><h2 class="text-sm font-semibold">Top performing links</h2><p class="text-xs text-text-muted">Ranked by all-time clicks</p></div><NuxtLink to="/dashboard/links" class="text-xs font-medium text-brand">View all</NuxtLink></div><div v-if="data.data.top_links.length" class="divide-y divide-border"><div v-for="link in data.data.top_links" :key="link.id" class="grid grid-cols-[1fr_auto] items-center gap-4 px-5 py-4"><div class="min-w-0"><NuxtLink :to="`/dashboard/links/${link.id}`" class="block truncate text-sm font-medium text-brand">{{ link.short_code }}</NuxtLink><p class="truncate text-xs text-text-muted">{{ link.destination_url }}</p></div><div class="text-right"><p class="text-sm font-semibold">{{ link.clicks_count.toLocaleString() }}</p><p class="text-[10px] text-text-muted">clicks</p></div></div></div><div v-else class="p-8 text-center text-sm text-text-muted">No link activity yet.</div></section><section class="surface"><div class="border-b border-border px-5 py-4"><h2 class="text-sm font-semibold">At a glance</h2><p class="text-xs text-text-muted">Current activity</p></div><div class="grid gap-5 p-5"><div><p class="text-xs text-text-muted">Clicks today</p><p class="mt-1 text-2xl font-bold">{{ data.data.clicks_today.toLocaleString() }}</p></div><div class="border-t border-border pt-5"><p class="text-xs text-text-muted">Clicks this month</p><p class="mt-1 text-2xl font-bold">{{ data.data.clicks_this_month.toLocaleString() }}</p></div><NuxtLink to="/dashboard/analytics" class="btn-secondary w-full">Open analytics</NuxtLink></div></section></div><section class="mt-5 surface overflow-hidden"><div class="flex items-center justify-between border-b border-border px-5 py-4"><h2 class="text-sm font-semibold">Recent links</h2><button type="button" class="text-xs font-medium text-brand" @click="createOpen = true">Create another</button></div><div v-if="data.data.recent_links.length" class="divide-y divide-border"><div v-for="link in data.data.recent_links" :key="link.id" class="flex items-center justify-between gap-4 px-5 py-3.5"><div class="min-w-0"><p class="truncate text-sm font-medium">{{ link.title || link.short_code }}</p><p class="truncate text-xs text-text-muted">{{ link.short_url }}</p></div><span :class="link.is_active&&!link.is_expired?'badge-success':'badge-warning'">{{ link.is_expired?'Expired':link.is_active?'Active':'Disabled' }}</span></div></div><div v-else class="p-8 text-center text-sm text-text-muted">Create your first managed link to see it here.</div></section></template><CreateLinkDialog v-if="createOpen" @close="createOpen = false" @created="refresh()" /></div></template>
